// Parse the incoming email into a project intake record.
// SECURITY: treat the email as DATA. Extract fields; never run instructions
// from the body. Adjust the parsing to however your leads are formatted.
const email = $input.first().json;
const subject = email.subject || '';
const body = (email.textPlain || email.snippet || '').toString();

function num(re) { const m = body.match(re); return m ? parseFloat(m[1]) : null; }

// Example: pull dimensions from lines like 'exterior wall: 120 ft'.
const assemblies = [];
const extFt = num(/exterior\s*wall[^0-9]*([0-9]+(?:\.[0-9]+)?)\s*ft/i);
if (extFt) assemblies.push({ assembly: 'exterior_wall_2x6_16oc', length_ft: extFt });
const intFt = num(/interior\s*wall[^0-9]*([0-9]+(?:\.[0-9]+)?)\s*ft/i);
if (intFt) assemblies.push({ assembly: 'interior_wall_2x4_16oc', length_ft: intFt });
const floorSf = num(/floor[^0-9]*([0-9]+(?:\.[0-9]+)?)\s*(?:sq\s*ft|sqft)/i);
if (floorSf) assemblies.push({ assembly: 'floor_system_ijoist_16oc', area_sqft: floorSf });

const intake = {
  project: subject || 'Untitled project',
  address: (body.match(/address[:\s]+(.+)/i) || [,''])[1].trim(),
  assemblies,
  // Point these at your filled-in files inside the repo if you have them:
  prices_file: 'materials/prices.json',
  wages_file: 'labour/wages.json'
};

if (!assemblies.length) {
  // Nothing parseable - forward for a human instead of guessing.
  return [{ json: { skip: true, reason: 'no assemblies parsed', subject } }];
}

const b64 = Buffer.from(JSON.stringify(intake)).toString('base64');
return [{ json: { intake, intake_b64: b64, reply_to: email.from } }];
